import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.ORnkkB96.js";const p=JSON.parse('{"title":"Screen guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/telas.md","filePath":"en/telas.md","lastUpdated":1792519643000}'),n={name:"en/telas.md"};function i(s,e,h,d,c,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="screen-guide" tabindex="-1">Screen guide <a class="header-anchor" href="#screen-guide" aria-label="Permalink to &quot;Screen guide&quot;">​</a></h1><p>An overview of what each area of the platform does, and the order to use them the first time. The typical flow goes from registering cameras → creating rules → receiving notifications, with training and integration coming later.</p><h2 id="cameras" tabindex="-1">Cameras <a class="header-anchor" href="#cameras" aria-label="Permalink to &quot;Cameras&quot;">​</a></h2><p>Where the video sources are registered. Each camera holds the RTSP URL and the credential (the password is <strong>encrypted</strong> at registration and only the capture worker decrypts it). From here you can test the connection before saving and see the camera in live video.</p><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><p>Organize cameras into sets (by site, by sector), which makes it easy to apply a rule or a permission to several cameras at once.</p><h2 id="live-video" tabindex="-1">Live video <a class="header-anchor" href="#live-video" aria-label="Permalink to &quot;Live video&quot;">​</a></h2><p>Shows the camera stream in the browser, served by the media gateway through the same address as the platform — <strong>no camera password ever reaches the page</strong>. This is where you check framing and detection zones.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>The heart of the operation. A rule watches the detections of one or more cameras and, when the condition happens (an object in a zone, dwell time over a threshold, a count), fires an <strong>action</strong>: notify, save a snapshot of the frame, call a signed webhook or an external system. Cooldown and confirmation avoid repeated alarms.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>The hub where people receive what the rules fired. A notification&#39;s target is <strong>users and groups</strong> of the platform itself; external delivery (WhatsApp, Telegram) goes out through an integration — typically a webhook to a tool like n8n, which delivers at the edge. Each alert can carry the moment&#39;s snapshot and a <strong>qualification</strong> link (confirm whether it was a real event), which feeds learning.</p><h2 id="detections-and-history" tabindex="-1">Detections and history <a class="header-anchor" href="#detections-and-history" aria-label="Permalink to &quot;Detections and history&quot;">​</a></h2><p>The record of what was detected over time, with filters by camera, period and type. It is what gives history to the dashboard and the event to the qualification link. Snapshot and clip retention is configurable (default: 30 days).</p><h2 id="training" tabindex="-1">Training <a class="header-anchor" href="#training" aria-label="Permalink to &quot;Training&quot;">​</a></h2><p>Where a custom model is trained from the qualified detections. A training job enters the queue and the worker processes it (on GPU, when available). When it finishes, the notice arrives in the hub.</p><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><p>People and permissions. Login can be local or via external identity (<strong>OIDC</strong> or <strong>LDAP/AD</strong>), which never creates an account on its own — it only authenticates someone an administrator has already linked.</p><h2 id="integrations-mcp" tabindex="-1">Integrations (MCP) <a class="header-anchor" href="#integrations-mcp" aria-label="Permalink to &quot;Integrations (MCP)&quot;">​</a></h2><p>Exposes Vision.AI as an <strong>MCP server</strong>: a ProAgentHub agent (or another MCP client such as Claude Desktop, Cursor or n8n) queries the platform in natural language. It is reached at the same address, under <code>/mcp/</code>.</p>',20)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
